steps.sampleSolution:
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

int main() {
    std::vector<int> codigos = {10, 20};
    std::unordered_map<std::string, int> status;
    codigos.push_back(30);
    status["ok"] = 200;
    for (const auto& c : codigos) {
        std::cout << c << "\n";
    }
    return 0;
}
